/*
V1-13 · E4 — POST do ENCERRAMENTO (somente leitura, um SELECT, modo gate). PASS = barreira CLOSED, 0 identidades,
booleanos true e, na conferência manual com o PRE da abertura: eventos_editor_externos_n, alocacoes_fp e exemplares_fp IGUAIS;
condicao_fp igual depois de restaurar o exemplar da PR-04B; demais *_fp mostram o que a homologação mudou.
*/

select jsonb_build_object(
  'executor',                                           current_user,
  'barreira',                                           (select s.mode from public.v1_13_barrier_state s where s.id = 1),
  'identidades_teste',                                  (select count(*) from public.v1_13_barrier_identity),
  'funcoes_barreira_canonicas',                         (select md5(p.prosrc) from pg_catalog.pg_proc p where p.oid = to_regprocedure('public.v1_13_assert_capability()')) = 'e4f710904f50e6e8c3f1d8e2337639e0'
                                 and (select md5(p.prosrc) from pg_catalog.pg_proc p where p.oid = to_regprocedure('public.v1_13_capability_open()')) = '32e2f636361732b497e8401e50f0bbe0',
  'sem_editor_fora_do_conjunto',                        not exists (select 1 from public.collection_membership m join public.collection c on c.id = m.collection_id
                                 where m.role = 'EDITOR' and (m.user_id not in (select up.id from public.user_profile up where md5(up.username) in ('827f042802bd9c8f2524e4ef0c69e980', 'c87549f021e1d4ecd308b7514ee54229', 'aff41bfce3aefe2cd8e48622f0db56a3', '0de10d7efb9cb0d4eb1a7ebbcaf57ef7')) or c.owner_user_id not in (select up.id from public.user_profile up where md5(up.username) in ('827f042802bd9c8f2524e4ef0c69e980', 'c87549f021e1d4ecd308b7514ee54229', 'aff41bfce3aefe2cd8e48622f0db56a3', '0de10d7efb9cb0d4eb1a7ebbcaf57ef7')))),
  'sem_auditoria_colecao_fora_do_conjunto',             not exists (select 1 from public.collection_activity_event e where e.owner_user_id not in (select up.id from public.user_profile up where md5(up.username) in ('827f042802bd9c8f2524e4ef0c69e980', 'c87549f021e1d4ecd308b7514ee54229', 'aff41bfce3aefe2cd8e48622f0db56a3', '0de10d7efb9cb0d4eb1a7ebbcaf57ef7'))),
  'admins_no_conjunto_n',                               (select count(*) from public.admin_user a where a.id in (select up.id from public.user_profile up where md5(up.username) in ('827f042802bd9c8f2524e4ef0c69e980', 'c87549f021e1d4ecd308b7514ee54229', 'aff41bfce3aefe2cd8e48622f0db56a3', '0de10d7efb9cb0d4eb1a7ebbcaf57ef7'))),
  'membros_fora_do_conjunto_nas_colecoes_do_titular_n', (select count(*) from public.collection_membership m
                                 where m.collection_id in (select c.id from public.collection c where c.owner_user_id = (select up.id from public.user_profile up where md5(up.username) = '827f042802bd9c8f2524e4ef0c69e980')) and m.user_id not in (select up.id from public.user_profile up where md5(up.username) in ('827f042802bd9c8f2524e4ef0c69e980', 'c87549f021e1d4ecd308b7514ee54229', 'aff41bfce3aefe2cd8e48622f0db56a3', '0de10d7efb9cb0d4eb1a7ebbcaf57ef7'))),
  'participacoes_do_conjunto_em_colecoes_de_fora_n',    (select count(*) from public.collection_membership m join public.collection c on c.id = m.collection_id
                                 where m.user_id in (select up.id from public.user_profile up where md5(up.username) in ('827f042802bd9c8f2524e4ef0c69e980', 'c87549f021e1d4ecd308b7514ee54229', 'aff41bfce3aefe2cd8e48622f0db56a3', '0de10d7efb9cb0d4eb1a7ebbcaf57ef7')) and c.owner_user_id not in (select up.id from public.user_profile up where md5(up.username) in ('827f042802bd9c8f2524e4ef0c69e980', 'c87549f021e1d4ecd308b7514ee54229', 'aff41bfce3aefe2cd8e48622f0db56a3', '0de10d7efb9cb0d4eb1a7ebbcaf57ef7'))),
  'eventos_editor_externos_n',                          (select count(*) from public.binder_activity_event b
                                 where b.actor_user_id is not null and b.actor_user_id <> b.owner_user_id and b.actor_user_id not in (select up.id from public.user_profile up where md5(up.username) in ('827f042802bd9c8f2524e4ef0c69e980', 'c87549f021e1d4ecd308b7514ee54229', 'aff41bfce3aefe2cd8e48622f0db56a3', '0de10d7efb9cb0d4eb1a7ebbcaf57ef7'))),
  'alocacoes_fp',                                       (select md5(coalesce(string_agg(ca.id::text || ':' || ca.physical_card_id::text || ':' || ca.collection_id::text, ',' order by ca.id::text || ':' || ca.physical_card_id::text || ':' || ca.collection_id::text), '')) from public.collection_allocation ca where ca.collection_id in (select c.id from public.collection c where c.owner_user_id = (select up.id from public.user_profile up where md5(up.username) = '827f042802bd9c8f2524e4ef0c69e980'))),
  'exemplares_fp',                                      (select md5(coalesce(string_agg(pc.id::text || ':' || pc.card_variant_id::text || ':' || pc.language_id::text || ':' || coalesce(pc.storage_container_id::text, ''), ',' order by pc.id::text || ':' || pc.card_variant_id::text || ':' || pc.language_id::text || ':' || coalesce(pc.storage_container_id::text, '')), '')) from public.physical_card pc join public.inventory i on i.id = pc.inventory_id where i.owner_user_id = (select up.id from public.user_profile up where md5(up.username) = '827f042802bd9c8f2524e4ef0c69e980')),
  'condicao_fp',                                        (select md5(coalesce(string_agg(pc.id::text || ':' || coalesce(pc.condition_code, ''), ',' order by pc.id::text || ':' || coalesce(pc.condition_code, '')), '')) from public.physical_card pc join public.inventory i on i.id = pc.inventory_id where i.owner_user_id = (select up.id from public.user_profile up where md5(up.username) = '827f042802bd9c8f2524e4ef0c69e980')),
  'fichario_fp',                                        (select md5(coalesce(string_agg(l.id::text || ':' || pg.page_number || ':' || s.row_index || ':' || s.column_index || ':' || coalesce(a.physical_card_id::text, '') || ':' || s.locked || ':' || coalesce(e.card_id::text, ''), ',' order by l.id::text || ':' || pg.page_number || ':' || s.row_index || ':' || s.column_index || ':' || coalesce(a.physical_card_id::text, '') || ':' || s.locked || ':' || coalesce(e.card_id::text, '')), '')) from public.collection_layout l join public.collection_layout_page pg on pg.layout_id = l.id
                                 join public.collection_layout_slot s on s.page_id = pg.id
                                 left join public.collection_layout_slot_assignment a on a.slot_id = s.id
                                 left join public.collection_layout_slot_expected_content e on e.slot_id = s.id
                                 where l.collection_id in (select c.id from public.collection c where c.owner_user_id = (select up.id from public.user_profile up where md5(up.username) = '827f042802bd9c8f2524e4ef0c69e980')) and (a.id is not null or s.locked or e.slot_id is not null)),
  'pokedex_fp',                                         (select md5(coalesce(string_agg(pa.collection_allocation_id::text || ':' || pa.pokedex_position_id::text || ':' || pa.assignment_basis, ',' order by pa.collection_allocation_id::text || ':' || pa.pokedex_position_id::text || ':' || pa.assignment_basis), '')) from public.collection_pokedex_position_assignment pa join public.collection_allocation ca on ca.id = pa.collection_allocation_id
                                 where ca.collection_id in (select c.id from public.collection c where c.owner_user_id = (select up.id from public.user_profile up where md5(up.username) = '827f042802bd9c8f2524e4ef0c69e980'))),
  'colecoes_fp',                                        (select md5(coalesce(string_agg(c.id::text || ':' || c.name || ':' || coalesce(c.description, '') || ':' || coalesce(c.cover_finish, '') || ':' || coalesce(c.cover_code, '') || ':' || coalesce(c.cover_logo_path, ''), ',' order by c.id::text || ':' || c.name || ':' || coalesce(c.description, '') || ':' || coalesce(c.cover_finish, '') || ':' || coalesce(c.cover_code, '') || ':' || coalesce(c.cover_logo_path, '')), '')) from public.collection c where c.owner_user_id = (select up.id from public.user_profile up where md5(up.username) = '827f042802bd9c8f2524e4ef0c69e980'))
) as e4_close_post;
